mapper.select:
SELECT userId, username, monthBalance, performanceRank FROM ( SELECT user_id as userId, user_name as username, SUM(balance) as monthBalance, RANK() OVER (ORDER BY SUM(balance) DESC) as performanceRank FROM dc_customer_performance WHERE del_flag = 0
AND YEAR(create_time) = #{year}
AND MONTH(create_time) = #{month}
AND create_time BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01') AND LAST_DAY(CURDATE())
GROUP BY user_id ) ranked_data
WHERE userId = #{userId}
